package com.example

/**
 * Grade 11 Science Syllabus Question Bank for Live Exam Hall.
 * Covers Terms 1, 2, and 3 with 60 distinct syllabus topic slots per term.
 * Each slot provides 30 distinct variants corresponding to papers 1 to 30.
 */
object ScienceGrade11QuestionBank {

  fun getQuestion(term: Int, paperIdx: Int, qNum: Int): MockExamQuestion {
    val cleanPaper = if (paperIdx in 1..30) paperIdx else 1
    val cleanQ = if (qNum in 1..60) qNum else 1
    val effectiveSlot = ((cleanQ - 1 + (cleanPaper - 1) * 7) % 60) + 1
    return when (term) {
      1 -> getTerm1Question(cleanPaper, cleanQ, effectiveSlot)
      2 -> getTerm2Question(cleanPaper, cleanQ, effectiveSlot)
      else -> getTerm3Question(cleanPaper, cleanQ, effectiveSlot)
    }
  }

  // ==========================================================================
  // GRADE 11 - TERM 1 (Slots 1 to 60)
  // ==========================================================================
  private fun getTerm1Question(paperIdx: Int, qNum: Int, slot: Int): MockExamQuestion {
    val v = paperIdx - 1
    val (topic, quad) = when (slot) {
      in 1..8 -> "ජීවයේ රසායනික පදනම හා එන්සයිම" to run {
        val enzymeList = listOf(
          Quad("ජෛව රසායනික ප්‍රතික්‍රියාවල සක්‍රියන ශක්තිය අඩු කරමින් ප්‍රතික්‍රියා වේගවත් කරන ජෛව උත්ප්‍රේරක මොනවාද?", listOf("එන්සයිම (ප්‍රෝටීන)", "විටමින්", "හෝමෝන පමණි", "ඛනිජ ලවණ"), 1, "එන්සයිම යනු ගෝලාකාර ප්‍රෝටීන වන අතර සක්‍රියන ශක්තිය අඩු කර ප්‍රතික්‍රියා උත්ප්‍රේරණය කරයි."),
          Quad("මිනිස් සිරුරේ බොහෝ එන්සයිමවල උපරිම ක්‍රියාකාරීත්වයක් දක්වන ප්‍රශස්ත උෂ්ණත්වය (Optimum Temperature) කොපමණද?", listOf("37 °C (35 °C - 40 °C)", "100 °C", "0 °C", "60 °C"), 1, "මිනිස් සිරුරේ සාමාන්‍ය උෂ්ණත්වය වන 37 °C දී එන්සයිම උපරිම කාර්යක්ෂමතාවයකින් ක්‍රියා කරයි."),
          Quad("ආමාශයේ ක්‍රියාත්මක වන පෙප්සින් එන්සයිමයේ ප්‍රශස්ත pH අගය කෙබඳු වේද?", listOf("ප්‍රබල ආම්ලික (pH 1.5 - 2.5)", "උදාසීන (pH 7.0)", "ක්ෂාරීය (pH 8.5)", "ප්‍රබල භාස්මික (pH 12)"), 1, "ආමාශයික HCl අම්ලය නිසා පෙප්සින් ප්‍රශස්තව ක්‍රියා කරන්නේ ආම්ලික pH 2 ආසන්නයේය."),
          Quad("එන්සයිමයක සක්‍රිය අඩවියට උපස්ථර අණුවක් බන්ධනය වීම පැහැදිලි කරන න්‍යාය කුමක්ද?", listOf("අගුල හා යතුර ආකෘතිය (Lock and Key Hypothesis)", "චාලක අණුක වාදය", "සමතුලිතතා වාදය", "ක්වොන්ටම් වාදය"), 1, "එන්සයිමයේ සක්‍රිය අඩවියේ හැඩය උපස්ථර අණුවට පරිපූරක වන බැවින් අගුලට යතුර මෙන් ගැළපේ."),
          Quad("අධික උෂ්ණත්වයකදී (උදා: 60 °C ට වැඩි) එන්සයිමයක ක්‍රියාකාරීත්වය ස්ථිරවම අඩපණ වීමට හේතුව කුමක්ද?", listOf("එන්සයිම ප්‍රෝටීන විස්වභාවිකරණය (Denaturation) වීම", "එන්සයිමය දියවීම", "උපස්ථරය විනාශ වීම", "ජලය නොමැති වීම"), 1, "අධික තාපය නිසා ප්‍රෝටීනයේ තෘතියික ව්‍යුහය හා සක්‍රිය අඩවියේ හැඩය බිඳවැටී විස්වභාවික වේ."),
          Quad("සෛලයේ ක්ෂණික ශක්ති ප්‍රභවය ලෙස ශක්ති මුදල (Energy Currency) නමින් හඳුන්වන අණුව කුමක්ද?", listOf("ATP (ඇඩිනොසීන් ට්‍රයිපොස්පේට්)", "ග්ලූකෝස්", "DNA", "ලිපිඩ"), 1, "ATP ජලවිච්ඡේදනයෙන් ADP සහ අකාබනික පොස්පේට් (Pi) සාදමින් 30.5 kJ mol⁻¹ ක ශක්තියක් නිදහස් කරයි."),
          Quad("DNA අණුවක ද්විත්ව හෙලික්සීය ව්‍යුහය (Double Helix) ප්‍රථමයෙන් අනාවරණය කළ විද්‍යාඥයින් දෙපළ කවුද?", listOf("ජේම්ස් වොට්සන් සහ ෆ්‍රැන්සිස් ක්‍රික්", "කාල් ලිනේයස් හා ඩාවින්", "ග්‍රෙගර් මෙන්ඩල්", "ලුවී පාස්චර්"), 1, "1953 දී වොට්සන් හා ක්‍රික් විසින් DNA හි ද්විත්ව හෙලික්සීය ආකෘතිය ඉදිරිපත් කරන ලදී."),
          Quad("එන්සයිමයක සක්‍රිය අඩවියට බන්ධනය වී උපස්ථරය බැඳීම වළක්වන ද්‍රව්‍ය හඳුන්වන්නේ කෙසේද?", listOf("තරඟකාරී නිෂේධක (Inhibitors)", "සහ-එන්සයිම", "සක්‍රියකාරක", "උපස්ථර"), 1, "නිෂේධක එන්සයිමයේ සක්‍රිය අඩවිය අවහිර කර ප්‍රතික්‍රියා ශීඝ්‍රතාව පහත හෙළයි.")
        )
        enzymeList[(slot - 1 + v).mod(enzymeList.size)]
      }
      in 9..16 -> "පදාර්ථයේ ව්‍යුහය හා ආවර්තිතා ගුණ" to run {
        val ptList = listOf(
          Quad("වායුමය අවස්ථාවේ පවතින පරමාණුවකින් බාහිරම ඉලෙක්ට්‍රෝනයක් ඉවත් කර ධන අයනයක් සෑදීමට අවශ්‍ය අවම ශක්තිය කුමක්ද?", listOf("පළමු අයනීකරණ ශක්තිය (1st Ionization Energy)", "ඉලෙක්ට්‍රෝන බන්ධුතාව", "විද්‍යුත් සෘණතාව", "බන්ධන ශක්තිය"), 1, "X(g) -> X⁺(g) + e⁻ ක්‍රියාවලිය සඳහා අවශ්‍ය ශක්තිය පළමු අයනීකරණ ශක්තියයි."),
          Quad("ආවර්තිතා වගුවේ ආවර්තයක් ඔස්සේ වමේ සිට දකුණට යන විට පළමු අයනීකරණ ශක්තියේ සාමාන්‍ය ප්‍රවණතාව කුමක්ද?", listOf("සාමාන්‍යයෙන් ක්‍රමයෙන් වැඩිවේ", "අඩුවේ", "වෙනස් නොවේ", "ශුන්‍ය වේ"), 1, "න්‍යෂ්ටික ආරෝපණය වැඩිවීම සහ පරමාණුක අරය අඩුවීම නිසා ඉලෙක්ට්‍රෝන ආකර්ෂණය වැඩිවේ."),
